/**
 * Handler-level unit tests for generateReportTool in src/tools/generate-report.ts.
 *
 * Tests all validation paths that return before reaching render(), so no mock needed.
 * Each validation path is independent — tested by omitting / malforming one field at a time.
 *
 * Run standalone:
 *   cd F:\Antigravity\brain\projects\pretext-pdf-mcp
 *   npx tsx --test test/generate-report-handler.test.ts
 */
import { describe, it } from 'node:test'
import assert from 'node:assert/strict'

const { generateReportTool } = await import('../src/tools/generate-report.js')
const handler = generateReportTool.handler

const VALID_SECTION = { heading: 'Introduction', body: 'This is the body.' }

// ─── Helpers ─────────────────────────────────────────────────────────────────

function parseError(result: Awaited<ReturnType<typeof handler>>) {
  assert.strictEqual(result.isError, true, 'expected isError: true')
  return JSON.parse(result.content[0]!.text) as { success: boolean; error: string; message: string }
}

// ─── Validation paths (all return before render()) ───────────────────────────

describe('generateReportTool.handler — missing title', () => {
  it('missing title returns VALIDATION_ERROR', async () => {
    const result = await handler({ sections: [VALID_SECTION] })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
    assert.ok(err.message.toLowerCase().includes('title'), `expected message to mention title, got: ${err.message}`)
  })

  it('title: null returns VALIDATION_ERROR', async () => {
    const result = await handler({ title: null, sections: [VALID_SECTION] })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
  })

  it('title: 123 (non-string) returns VALIDATION_ERROR', async () => {
    const result = await handler({ title: 123, sections: [VALID_SECTION] })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
  })
})

describe('generateReportTool.handler — invalid sections', () => {
  it('empty sections array returns VALIDATION_ERROR', async () => {
    const result = await handler({ title: 'T', sections: [] })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
    assert.ok(err.message.toLowerCase().includes('sections'))
  })

  it('sections: undefined returns VALIDATION_ERROR', async () => {
    const result = await handler({ title: 'T' })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
  })

  it('sections: "string" (non-array) returns VALIDATION_ERROR', async () => {
    const result = await handler({ title: 'T', sections: 'not-an-array' })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
  })

  it('section with missing heading returns VALIDATION_ERROR', async () => {
    const result = await handler({ title: 'T', sections: [{ body: 'B' }] })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
    assert.ok(err.message.includes('heading'))
  })

  it('section with missing body returns VALIDATION_ERROR', async () => {
    const result = await handler({ title: 'T', sections: [{ heading: 'H' }] })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
    assert.ok(err.message.includes('body'))
  })
})

describe('generateReportTool.handler — callout validation', () => {
  it('invalid callout style returns VALIDATION_ERROR with message about callout.style', async () => {
    const result = await handler({
      title: 'T',
      sections: [{ heading: 'H', body: 'B', callout: { style: 'danger', text: 'Alert!' } }],
    })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
    assert.ok(err.message.includes('callout.style'), `expected message about callout.style, got: ${err.message}`)
  })

  it('callout with empty text returns VALIDATION_ERROR', async () => {
    const result = await handler({
      title: 'T',
      sections: [{ heading: 'H', body: 'B', callout: { style: 'info', text: '' } }],
    })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
    assert.ok(err.message.includes('callout.text'))
  })

  it('callout with non-object value returns VALIDATION_ERROR', async () => {
    const result = await handler({
      title: 'T',
      sections: [{ heading: 'H', body: 'B', callout: 'not-an-object' }],
    })
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
  })
})

describe('generateReportTool.handler — unsafe keys guard', () => {
  it('args with __proto__ key returns VALIDATION_ERROR about unsafe keys', async () => {
    // Build an args object that has __proto__ as an enumerable own property
    const args = JSON.parse('{"title":"T","sections":[{"heading":"H","body":"B"}],"__proto__":{"x":1}}')
    const result = await handler(args)
    const err = parseError(result)
    assert.strictEqual(err.error, 'VALIDATION_ERROR')
    assert.ok(err.message.toLowerCase().includes('unsafe'), `expected 'unsafe' in message, got: ${err.message}`)
  })
})

describe('generateReportTool.handler — response shape contract', () => {
  it('happy path or render error both produce a content[0].text JSON string', async () => {
    const result = await handler({ title: 'My Report', sections: [VALID_SECTION] })
    assert.ok(Array.isArray(result.content), 'content must be an array')
    assert.ok(result.content.length > 0, 'content must be non-empty')
    const text = result.content[0]!.text
    assert.ok(typeof text === 'string', 'content[0].text must be a string')
    const parsed = JSON.parse(text) as Record<string, unknown>
    if (result.isError) {
      assert.strictEqual(parsed.success, false)
      assert.ok(typeof parsed.error === 'string', 'error field must be a string on error path')
      assert.ok(typeof parsed.message === 'string', 'message field must be a string on error path')
    } else {
      assert.strictEqual(parsed.success, true)
      assert.ok(typeof parsed.base64 === 'string', 'base64 must be a string on success path')
      assert.ok(typeof parsed.filename === 'string', 'filename must be a string on success path')
      assert.ok((parsed.filename as string).endsWith('.pdf'), 'filename must end with .pdf')
    }
  })
})

import { render } from 'pretext-pdf'
import type { PdfDocument, ContentElement, ColumnDef } from 'pretext-pdf'
import { toBase64 } from '../utils/base64.js'
import { hasUnsafeKeys, runDocumentSafetyChecks } from '../utils/safety.js'
import { assertOutputSize, MAX_REPORT_SECTIONS } from '../utils/limits.js'

interface ReportSection {
  heading: string
  body: string
  table?: { headers: string[]; rows: string[][] }
  callout?: { style: 'info' | 'warning' | 'tip' | 'note'; text: string }
}

interface ReportInput {
  title: string
  subtitle?: string
  author?: string
  date?: string
  include_toc?: boolean
  sections: ReportSection[]
}

const CALLOUT_COLORS: Record<string, string> = {
  info: '#0070f3',
  warning: '#f59e0b',
  tip: '#10b981',
  note: '#6366f1',
}

const VALID_CALLOUT_STYLES = Object.keys(CALLOUT_COLORS)

function todayISO(): string {
  return new Date().toISOString().slice(0, 10)
}

export function buildReportDocument(input: ReportInput): PdfDocument {
  const includeToc = input.include_toc !== false
  const date = input.date ?? todayISO()

  const content: ContentElement[] = [
    // Cover block
    { type: 'spacer', height: 40 },
    {
      type: 'heading',
      level: 1,
      text: input.title,
      fontSize: 28,
      color: '#1a1a2e',
      align: 'center',
      spaceAfter: 10,
      bookmark: false,
    },
  ]

  if (input.subtitle) {
    content.push({
      type: 'paragraph',
      text: input.subtitle,
      fontSize: 14,
      color: '#555555',
      align: 'center',
      spaceAfter: 10,
    })
  }

  const metaParts: string[] = []
  if (input.author) metaParts.push(input.author)
  metaParts.push(date)
  content.push({
    type: 'paragraph',
    text: metaParts.join('  ·  '),
    fontSize: 10,
    color: '#888888',
    align: 'center',
    spaceAfter: 6,
  })

  content.push({ type: 'hr', color: '#1a1a2e', thickness: 2, spaceAfter: 40 })

  // TOC
  if (includeToc) {
    content.push({
      type: 'toc',
      title: 'Contents',
      showTitle: true,
      leader: '.',
      minLevel: 1,
      maxLevel: 2,
      fontSize: 11,
      spaceAfter: 24,
    })
    content.push({ type: 'page-break' })
  }

  // Sections
  for (const section of input.sections) {
    content.push({
      type: 'heading',
      level: 1,
      text: section.heading,
      anchor: section.heading.toLowerCase().replace(/\s+/g, '-'),
      spaceAfter: 8,
    })

    // Body: split on double newlines for multiple paragraphs, single newlines become spaces
    const paragraphs = section.body.split(/\n\n+/)
    for (const para of paragraphs) {
      if (para.trim()) {
        content.push({
          type: 'paragraph',
          text: para.trim().replace(/\n/g, ' '),
          spaceAfter: 8,
        })
      }
    }

    if (section.table) {
      const { headers, rows } = section.table
      const fracColumns: Pick<ColumnDef, 'width' | 'align'>[] = headers.map(() => ({ width: '1*' as `${number}*`, align: 'left' as const }))

      const headerRow = {
        isHeader: true,
        cells: headers.map(h => ({ text: h, fontWeight: 700, color: '#ffffff' })),
      }
      const dataRows = rows.map(row => ({
        cells: row.map(cell => ({ text: cell })),
      }))

      content.push({
        type: 'table',
        columns: fracColumns,
        rows: [headerRow, ...dataRows],
        headerBgColor: '#1a1a2e',
        borderColor: '#dddddd',
        borderWidth: 0.5,
        cellPaddingH: 8,
        cellPaddingV: 6,
        spaceAfter: 12,
      })
    }

    if (section.callout) {
      const borderColor = CALLOUT_COLORS[section.callout.style] ?? '#888888'
      content.push({
        type: 'callout',
        style: section.callout.style,
        content: section.callout.text,
        borderColor,
        spaceAfter: 12,
      })
    }
  }

  return {
    pageSize: 'A4',
    margins: { top: 60, bottom: 60, left: 64, right: 64 },
    defaultFontSize: 11,
    bookmarks: { minLevel: 1, maxLevel: 3 },
    header: {
      text: input.title,
      fontSize: 8,
      color: '#999999',
      align: 'right',
    },
    footer: {
      text: 'Page {{pageNumber}} of {{totalPages}}',
      fontSize: 8,
      color: '#999999',
      align: 'center',
    },
    metadata: {
      title: input.title,
      author: input.author,
      subject: input.subtitle,
    },
    content,
  }
}

export const generateReportTool = {
  schema: {
    name: 'generate_report',
    description:
      'Generate a professional multi-section report PDF. Features: auto-generated TOC, per-section headings with PDF bookmarks, page-numbered footer, running header, optional tables and callout boxes per section. Returns base64-encoded PDF.',
    inputSchema: {
      type: 'object' as const,
      properties: {
        title: { type: 'string', description: 'Report title' },
        subtitle: { type: 'string', description: 'Report subtitle or description' },
        author: { type: 'string', description: 'Author name' },
        date: { type: 'string', description: 'Date string. Defaults to today.' },
        include_toc: {
          type: 'boolean',
          description: 'Include a Table of Contents page. Default: true',
          default: true,
        },
        sections: {
          type: 'array',
          description: 'Report sections',
          items: {
            type: 'object',
            properties: {
              heading: { type: 'string', description: 'Section heading' },
              body: {
                type: 'string',
                description:
                  'Section body text. Use double newlines (\\n\\n) to separate paragraphs.',
              },
              table: {
                type: 'object',
                description: 'Optional data table',
                properties: {
                  headers: { type: 'array', items: { type: 'string' } },
                  rows: {
                    type: 'array',
                    items: { type: 'array', items: { type: 'string' } },
                  },
                },
                required: ['headers', 'rows'],
              },
              callout: {
                type: 'object',
                description: 'Optional callout / alert box',
                properties: {
                  style: {
                    type: 'string',
                    enum: ['info', 'warning', 'tip', 'note'],
                  },
                  text: { type: 'string' },
                },
                required: ['style', 'text'],
              },
            },
            required: ['heading', 'body'],
          },
        },
        filename: { type: 'string', description: 'Suggested filename without .pdf extension.' },
      },
      required: ['title', 'sections'],
    },
  },

  handler: async (args: Record<string, unknown>) => {
    try {
      // Early guard: catch __proto__ / constructor / prototype pollution before
      // iterating section / table / callout field values below. The
      // constructed `doc` is built internally and cannot carry pollution from
      // args, but a polluted args object could crash field accessors mid-loop.
      // A second `runDocumentSafetyChecks(doc)` call later validates the
      // *built* doc as defence-in-depth against future builder drift.
      if (hasUnsafeKeys(args)) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: 'Input contains unsafe keys (__proto__, constructor, prototype)' }) }],
          isError: true,
        }
      }

      if (!args.title || typeof args.title !== 'string') {
        return {
          content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: 'title is required' }) }],
          isError: true,
        }
      }
      const sections = args.sections as ReportSection[]
      if (!Array.isArray(sections) || sections.length === 0) {
        return {
          content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: 'sections must be a non-empty array' }) }],
          isError: true,
        }
      }
      if (sections.length > MAX_REPORT_SECTIONS) {
        return { content: [{ type: 'text', text: `sections exceeds limit of ${MAX_REPORT_SECTIONS}` }], isError: true }
      }
      for (let i = 0; i < sections.length; i++) {
        const s = sections[i]
        if (!s || typeof s !== 'object') {
          return { content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: `sections[${i}] must be an object` }) }], isError: true }
        }
        if (typeof s.heading !== 'string' || s.heading.trim() === '') {
          return { content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: `sections[${i}].heading is required and must be a non-empty string` }) }], isError: true }
        }
        if (typeof s.body !== 'string') {
          return { content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: `sections[${i}].body is required and must be a string` }) }], isError: true }
        }
        if (s.table !== undefined) {
          if (typeof s.table !== 'object' || Array.isArray(s.table)) {
            return { content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: `sections[${i}].table must be an object` }) }], isError: true }
          }
          if (!Array.isArray(s.table.headers)) {
            return { content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: `sections[${i}].table.headers must be an array of strings` }) }], isError: true }
          }
          if (!Array.isArray(s.table.rows) || !s.table.rows.every((r: unknown) => Array.isArray(r))) {
            return { content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: `sections[${i}].table.rows must be an array of arrays` }) }], isError: true }
          }
        }
        if (s.callout !== undefined) {
          if (typeof s.callout !== 'object' || Array.isArray(s.callout)) {
            return { content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: `sections[${i}].callout must be an object` }) }], isError: true }
          }
          if (typeof s.callout.text !== 'string' || s.callout.text.trim() === '') {
            return { content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: `sections[${i}].callout.text is required and must be a non-empty string` }) }], isError: true }
          }
          if (s.callout.style !== undefined && !VALID_CALLOUT_STYLES.includes(s.callout.style)) {
            return { content: [{ type: 'text', text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message: `sections[${i}].callout.style must be one of: info, warning, tip, note` }) }], isError: true }
          }
        }
      }

      const input = args as unknown as ReportInput
      const doc = buildReportDocument(input)

      // Defence-in-depth: validate the built doc structurally before render.
      const safetyError = runDocumentSafetyChecks(doc)
      if (safetyError) return safetyError

      const bytes = await render(doc)
      assertOutputSize(bytes, 'generate_report')
      const base64 = toBase64(bytes)
      const filename = ((args.filename as string) || `report-${Date.now()}`) + '.pdf'
      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify({ success: true, base64, filename, size_bytes: bytes.length }),
          },
        ],
      }
    } catch (err: unknown) {
      const e = err as { code?: string; message?: string }
      const message = err instanceof Error ? err.message : String(err)
      if (!(err instanceof Error) || !e.code) {
        process.stderr.write(JSON.stringify({ ts: new Date().toISOString(), level: 'error', tool: 'generate_report', msg: message }) + '\n')
      }
      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify({ success: false, error: e.code ?? 'UNKNOWN_ERROR', message }),
          },
        ],
        isError: true,
      }
    }
  },
}

export function toBase64(bytes: Uint8Array): string {
  return Buffer.from(bytes).toString('base64')
}

import { validateDocument } from 'pretext-pdf'

/**
 * Structural check for prototype-pollution attack keys.
 * Walks the object tree and rejects documents containing __proto__, constructor,
 * or prototype keys. Depth limit prevents runaway recursion on cyclic structures.
 *
 * Shared by every MCP tool that accepts user-supplied object input.
 */
export function hasUnsafeKeys(node: unknown, depth = 0): boolean {
  if (depth > 64) return true // Reject deeply nested structures to prevent DoS
  if (node === null || typeof node !== 'object') return false

  for (const key of Object.keys(node as Record<string, unknown>)) {
    if (key === '__proto__' || key === 'constructor' || key === 'prototype') return true
    if (hasUnsafeKeys((node as Record<string, unknown>)[key], depth + 1)) return true
  }
  return false
}

/** Standard MCP error envelope returned by the safety helpers. */
export interface SafetyErrorResponse {
  content: Array<{ type: 'text'; text: string }>
  isError: true
}

function safetyError(message: string): SafetyErrorResponse {
  return {
    content: [
      {
        type: 'text',
        text: JSON.stringify({ success: false, error: 'VALIDATION_ERROR', message }),
      },
    ],
    isError: true,
  }
}

/**
 * Defence-in-depth check applied to any document about to be rendered.
 *
 * Performs two checks in order:
 *   1. `hasUnsafeKeys()` — reject prototype-pollution payloads before any further work.
 *   2. `validateDocument()` — structural schema validation against the pretext-pdf contract.
 *
 * Returns `null` when the document is safe to render, or an MCP error response
 * when it should be rejected. Callers should `return` the response unchanged.
 */
export function runDocumentSafetyChecks(doc: unknown): SafetyErrorResponse | null {
  if (hasUnsafeKeys(doc)) {
    return safetyError('Document contains unsafe keys (__proto__, constructor, prototype)')
  }
  if (doc === null || typeof doc !== 'object' || Array.isArray(doc)) {
    return safetyError('Document must be a non-null object')
  }
  const validation = validateDocument(doc as Record<string, unknown>)
  if (!validation.valid) {
    const messages = validation.errors
      .map((e: { path: string; message: string }) => `${e.path}: ${e.message}`)
      .join('; ')
    return safetyError(messages)
  }
  return null
}

export const MAX_PDF_OUTPUT_BYTES = 50 * 1024 * 1024 // 50MB
export const MAX_CONTENT_ELEMENTS = 500
export const MAX_REPORT_SECTIONS = 100
export const JSON_MAX_DEPTH = 50
export const MAX_MARKDOWN_CHARS = 200_000

export function checkJsonDepth(raw: string, max = JSON_MAX_DEPTH): void {
  let depth = 0
  let maxDepth = 0
  let inString = false
  let escaped = false
  for (let i = 0; i < raw.length; i++) {
    const ch = raw[i]
    if (escaped) { escaped = false; continue }
    if (inString) {
      if (ch === '\\') escaped = true
      else if (ch === '"') inString = false
      continue
    }
    if (ch === '"') { inString = true; continue }
    if (ch === '{' || ch === '[') {
      depth++
      if (depth > maxDepth) maxDepth = depth
    } else if (ch === '}' || ch === ']') {
      depth--
    }
  }
  if (maxDepth > max) {
    throw new Error(`JSON depth ${maxDepth} exceeds limit ${max}`)
  }
}

export function assertOutputSize(bytes: Uint8Array, toolName: string): void {
  if (bytes.byteLength > MAX_PDF_OUTPUT_BYTES) {
    throw new Error(`${toolName}: output PDF exceeds ${MAX_PDF_OUTPUT_BYTES / 1024 / 1024}MB limit (${(bytes.byteLength / 1024 / 1024).toFixed(1)}MB)`)
  }
}
